// Drift-detection mock tests (hand-written; not generated by crudgen).
//
// These prove the two halves of the refresh architecture end-to-end against
// the in-process mock:
//
//  1. DRIFT IS VISIBLE: an out-of-band edit to the mock store (simulating a
//     webapp user) — both to a TYPED attribute (cohort name/description,
//     dashboard title) and to a JSONENCODE blob (cohort groups) — is picked
//     up by `terraform refresh` (Read uses client.MergeRead: the wire wins
//     wherever it carries a field) and produces a non-empty plan; re-applying
//     the config converges the server back and reaches a clean plan.
//
//  2. NO FALSE DRIFT: a jsonencode blob written in NON-canonical form
//     (spaces, unsorted keys) stays stable across apply and refresh even
//     though the wire echoes it re-rendered in canonical form — the
//     jsontypes.Normalized semantic equality payoff. Without Normalized the
//     create itself fails with "Provider produced inconsistent result after
//     apply" and every refresh would produce a perpetual diff.
package provider

import (
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
	"github.com/hashicorp/terraform-plugin-testing/terraform"
)

// storedFieldEquals asserts that the (single) object in the mock store carries
// field == want, proving a re-apply converged the server side after drift.
func storedFieldEquals(srv *mockServer, field, want string) resource.TestCheckFunc {
	return func(*terraform.State) error {
		var got any
		found := false
		srv.mutateStored(func(id string, obj map[string]any) {
			got = obj[field]
			found = true
		})
		if !found {
			return fmt.Errorf("mock store is empty")
		}
		if s, _ := got.(string); s != want {
			return fmt.Errorf("mock store %s = %v, want %q", field, got, want)
		}
		return nil
	}
}

// TestAccCohort_driftDetection: out-of-band edits to a typed attribute (name)
// AND a jsonencode blob (groups) must surface as a non-empty plan after
// refresh, and re-applying the config must converge.
func TestAccCohort_driftDetectionMock(t *testing.T) {
	srv := newMockServer(t, mockOpts{enveloped: true, idField: "id"})

	config := providerConfig(srv.URL, `
resource "mixpanel_cohort" "test" {
  name        = "drift-orig"
  description = "original description"
  groups      = jsonencode([{ event = "signup", window = 30 }])
}`)

	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testProtoV6,
		Steps: []resource.TestStep{
			{
				// Create; the implicit post-apply refresh+plan asserts idempotency.
				Config: config,
				Check: resource.ComposeTestCheckFunc(
					resource.TestCheckResourceAttr("mixpanel_cohort.test", "name", "drift-orig"),
				),
			},
			{
				// A webapp user renames the cohort and rewrites its groups
				// definition out of band. The refresh must pull BOTH the typed
				// attribute and the jsonencode blob from the wire (MergeRead:
				// wire-preferred), making the drift visible as a non-empty plan.
				PreConfig: func() {
					srv.mutateStored(func(id string, obj map[string]any) {
						obj["name"] = "renamed-out-of-band"
						obj["groups"] = []any{map[string]any{"event": "purchase", "window": float64(7)}}
					})
				},
				RefreshState:       true,
				ExpectNonEmptyPlan: true,
				Check: resource.ComposeTestCheckFunc(
					// Refreshed state must reflect the server, not the old config.
					resource.TestCheckResourceAttr("mixpanel_cohort.test", "name", "renamed-out-of-band"),
					resource.TestCheckResourceAttr("mixpanel_cohort.test", "groups", `[{"event":"purchase","window":7}]`),
					// The wire-omitted field keeps its prior value (echo-gap rule).
					resource.TestCheckResourceAttr("mixpanel_cohort.test", "description", "original description"),
				),
			},
			{
				// Re-applying the configuration converges the server back and
				// reaches a clean plan (implicit post-apply idempotency check).
				Config: config,
				Check: resource.ComposeTestCheckFunc(
					resource.TestCheckResourceAttr("mixpanel_cohort.test", "name", "drift-orig"),
					storedFieldEquals(srv, "name", "drift-orig"),
				),
			},
		},
	})
}

// TestAccDashboard_driftDetection: an out-of-band title change must surface
// as drift and converge on re-apply.
func TestAccDashboard_driftDetectionMock(t *testing.T) {
	srv := newMockServer(t, mockOpts{enveloped: true, idField: "id"})

	config := providerConfig(srv.URL, `
resource "mixpanel_dashboard" "test" {
  title = "quarterly KPIs"
}`)

	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testProtoV6,
		Steps: []resource.TestStep{
			{
				Config: config,
				Check:  resource.TestCheckResourceAttr("mixpanel_dashboard.test", "title", "quarterly KPIs"),
			},
			{
				PreConfig: func() {
					srv.mutateStored(func(id string, obj map[string]any) {
						obj["title"] = "renamed in webapp"
					})
				},
				RefreshState:       true,
				ExpectNonEmptyPlan: true,
				Check:              resource.TestCheckResourceAttr("mixpanel_dashboard.test", "title", "renamed in webapp"),
			},
			{
				Config: config,
				Check: resource.ComposeTestCheckFunc(
					resource.TestCheckResourceAttr("mixpanel_dashboard.test", "title", "quarterly KPIs"),
					storedFieldEquals(srv, "title", "quarterly KPIs"),
				),
			},
		},
	})
}

// TestAccCohort_noFalseDriftOnNormalizedJSON: a groups blob written in
// non-canonical JSON (extra whitespace, unsorted keys) must survive apply and
// refresh with a clean plan even though the provider re-renders the wire echo
// canonically (sorted keys, no spaces). This is the jsontypes.Normalized
// semantic-equality guarantee; with plain strings this test fails at create
// with "Provider produced inconsistent result after apply".
func TestAccCohort_noFalseDriftOnNormalizedJSON(t *testing.T) {
	srv := newMockServer(t, mockOpts{enveloped: true, idField: "id"})

	// NOTE the non-canonical rendering: spaces after colons/commas and keys
	// deliberately out of alphabetical order. The wire echo comes back as
	// [{"event":"signup","window":30}].
	config := providerConfig(srv.URL, `
resource "mixpanel_cohort" "test" {
  name   = "normalized-json"
  groups = "[{\"window\": 30, \"event\": \"signup\"}]"
}`)

	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testProtoV6,
		Steps: []resource.TestStep{
			{
				// Create must succeed (semantic equality absorbs the canonical
				// echo) and the implicit post-apply refresh+plan must be empty.
				Config: config,
				Check: resource.TestCheckResourceAttr(
					"mixpanel_cohort.test", "groups", `[{"window": 30, "event": "signup"}]`),
			},
			{
				// An explicit refresh must also keep the plan empty: the wire
				// echoes the canonical rendering, which is byte-different but
				// semantically equal to the state value.
				RefreshState: true,
				Check: resource.TestCheckResourceAttr(
					"mixpanel_cohort.test", "groups", `[{"window": 30, "event": "signup"}]`),
			},
			{
				// And a plain re-plan/apply of the same config is a no-op.
				Config: config,
			},
		},
	})
}
